using System.Net;
using System.Security.Claims;
using Microsoft.AspNetCore.Antiforgery;
using Microsoft.Data.Sqlite;

namespace CltPlusPlus.Employee;

public static class PoliceCallIntake
{
    public static void Map(WebApplication app)
    {
        var dbPath=app.Configuration["CLTPP_PUBLIC_SAFETY_DB"]??Path.Combine(AppContext.BaseDirectory,"data","public-safety.db");
        Directory.CreateDirectory(Path.GetDirectoryName(dbPath)!);Ensure(dbPath);

        app.MapGet("/police-calls",async(HttpContext ctx,string? q,string? status)=>
        {
            if(!CanPolice(ctx.User))return Results.Forbid();await using var cn=Open(dbPath);await cn.OpenAsync();var c=cn.CreateCommand();
            c.CommandText="SELECT Id,CallNumber,CallType,Priority,Location,Status,CreatedBy,CreatedAt FROM PoliceCalls WHERE ($q='' OR CallNumber LIKE $like OR CallType LIKE $like OR Location LIKE $like OR CallerName LIKE $like OR CallerPhone LIKE $like OR InitialNarrative LIKE $like) AND ($s='' OR Status=$s) ORDER BY CreatedAt DESC LIMIT 300";
            c.Parameters.AddWithValue("$q",q??"");c.Parameters.AddWithValue("$like","%"+(q??"")+"%");c.Parameters.AddWithValue("$s",status??"");var rows=new List<string>();
            await using var r=await c.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add($"<tr><td><a href='/police-calls/{r.GetString(0)}'><b>{H(r.GetString(1))}</b></a></td><td>{H(r.GetString(2))}</td><td>{H(r.GetString(3))}</td><td>{H(r.GetString(4))}</td><td>{H(r.GetString(5))}</td><td>{H(r.GetString(6))}</td><td>{H(r.GetString(7))}</td></tr>");
            return Html(Page("Police calls",$"<main class='wrap'><section class='page-head'><div><span class='eyebrow'>POLICE · CALL INTAKE</span><h1>Calls & intake</h1><p>Create and manage police call intake records and recorded Amazon Chime calls.</p></div><a class='button' href='/police-calls/new'>New call</a></section><form class='filters'><input name='q' value='{H(q)}' placeholder='Call number, type, location, caller, phone'/><select name='status'><option value=''>All statuses</option>{Opts(new[]{"Open","Assigned","In Progress","Disposition Pending","Closed"},status)}</select><button>Search</button></form><section class='table-card'><table><thead><tr><th>Call</th><th>Type</th><th>Priority</th><th>Location</th><th>Status</th><th>Created by</th><th>Created</th></tr></thead><tbody>{(rows.Count>0?string.Join("",rows):"<tr><td colspan='7'>No calls found.</td></tr>")}</tbody></table></section></main>"));
        }).RequireAuthorization();

        app.MapGet("/police-calls/new",(HttpContext ctx,IAntiforgery anti)=>
        {
            if(!CanPolice(ctx.User))return Results.Forbid();var t=anti.GetAndStoreTokens(ctx).RequestToken!;
            return Html(Page("New police call",$"""<main class='wrap'><a href='/police-calls'>← Calls</a><section class='card'><span class='eyebrow'>POLICE · CALL INTAKE</span><h1>Create call</h1><p>A callback phone number is required because officers can place a recorded Amazon Chime call from the saved intake.</p><form method='post' action='/police-calls'><input type='hidden' name='__RequestVerificationToken' value='{H(t)}'/><label>Call type<input name='callType' required placeholder='Disturbance, larceny, welfare check, traffic, etc.'/></label><label>Priority<select name='priority'><option>Routine</option><option>Priority</option><option>Urgent</option><option>Emergency</option></select></label><label>Location<input name='location' required/></label><label>Location details<input name='locationDetails' placeholder='Apartment, floor, landmark, access instructions'/></label><label>Caller name<input name='callerName'/></label><label>Caller phone<input type='tel' name='callerPhone' required autocomplete='tel' placeholder='+17045551212'/></label><label>Caller email<input type='email' name='callerEmail'/></label><label>Caller relationship<input name='callerRelationship'/></label><label>Anonymous caller<select name='anonymous'><option value='false'>No</option><option value='true'>Yes</option></select></label><label>Safety flags<textarea name='safetyFlags' rows='3' placeholder='Weapons reported, hazards, animals, access concerns, etc.'></textarea></label><label>Initial narrative<textarea name='narrative' rows='10' required></textarea></label><button>Create call</button></form></section></main>"""));
        }).RequireAuthorization();

        app.MapPost("/police-calls",async(HttpContext ctx,IAntiforgery anti)=>
        {
            if(!CanPolice(ctx.User))return Results.Forbid();await anti.ValidateRequestAsync(ctx);var f=await ctx.Request.ReadFormAsync();var type=f["callType"].ToString().Trim();var loc=f["location"].ToString().Trim();var narrative=f["narrative"].ToString().Trim();var phone=f["callerPhone"].ToString().Trim();
            if(type.Length==0||loc.Length==0||narrative.Length==0||phone.Length==0)return Results.BadRequest("Call type, location, caller phone, and narrative are required.");
            var id=Guid.NewGuid();var num=$"CALL-{DateTime.UtcNow:yyMMdd}-{Random.Shared.Next(100000,999999)}";var now=Now();
            await Exec(dbPath,"INSERT INTO PoliceCalls(Id,CallNumber,CallType,Priority,Location,LocationDetails,CallerName,CallerPhone,CallerEmail,CallerRelationship,AnonymousCaller,SafetyFlags,InitialNarrative,Status,CreatedBy,CreatedAt,UpdatedAt) VALUES($i,$n,$ct,$p,$l,$ld,$cn,$cp,$ce,$cr,$a,$sf,$nr,'Open',$by,$t,$t)",("$i",id),("$n",num),("$ct",type),("$p",f["priority"]),("$l",loc),("$ld",f["locationDetails"]),("$cn",f["callerName"]),("$cp",phone),("$ce",f["callerEmail"]),("$cr",f["callerRelationship"]),("$a",f["anonymous"].ToString()=="true"?1:0),("$sf",f["safetyFlags"]),("$nr",narrative),("$by",ctx.User.Identity?.Name??"officer"),("$t",now));
            await History(dbPath,id,ctx.User.Identity?.Name??"officer","Created",type+" at "+loc+"; callback "+phone);return Results.Redirect($"/police-calls/{id}");
        }).RequireAuthorization();

        app.MapGet("/police-calls/{id:guid}",async(Guid id,HttpContext ctx,IAntiforgery anti)=>
        {
            if(!CanPolice(ctx.User))return Results.Forbid();var x=await Load(dbPath,id);if(x is null)return Results.NotFound();var t=anti.GetAndStoreTokens(ctx).RequestToken!;var people=await People(dbPath,id);var vehicles=await Vehicles(dbPath,id);var hist=await Hist(dbPath,id);var reports=await ReportOptions(dbPath,x.Value.ExpressReportId);
            return Html(Page(x.Value.Number,$"""<main class='wrap'><a href='/police-calls'>← Calls</a><section class='page-head'><div><span class='eyebrow'>POLICE CALL · {H(x.Value.Status)}</span><h1>{H(x.Value.Number)}</h1><p>{H(x.Value.Type)} · {H(x.Value.Priority)}</p></div><a class='button' href='/police-calls/{id}/chime'>Call {H(x.Value.CallerPhone)} via Chime</a></section><div class='detail-grid'><section><section class='card'><dl><dt>Location</dt><dd>{H(x.Value.Location)}</dd><dt>Location details</dt><dd>{H(x.Value.LocationDetails)}</dd><dt>Caller</dt><dd>{(x.Value.Anonymous?"Anonymous":H(x.Value.CallerName+" · "+x.Value.CallerPhone+" · "+x.Value.CallerEmail))}</dd><dt>Callback phone</dt><dd>{H(x.Value.CallerPhone)}</dd><dt>Safety flags</dt><dd>{H(x.Value.SafetyFlags)}</dd></dl><h2>Initial narrative</h2><p style='white-space:pre-wrap'>{H(x.Value.Narrative)}</p><h2>Officer supplements</h2>{await Supplements(dbPath,id)}</section><section class='card'><h2>People</h2>{people}</section><section class='card'><h2>Vehicles</h2>{vehicles}</section><section class='card'><h2>History</h2>{hist}</section></section><aside><section class='card'><h2>Update call</h2><form method='post' action='/police-calls/{id}/update'><input type='hidden' name='__RequestVerificationToken' value='{H(t)}'/><label>Status<select name='status'>{Opts(new[]{"Open","Assigned","In Progress","Disposition Pending","Closed"},x.Value.Status)}</select></label><label>Assigned officer / unit<input name='assignedTo' value='{H(x.Value.AssignedTo)}'/></label><label>Disposition<input name='disposition' value='{H(x.Value.Disposition)}'/></label><label>Link Express Report<select name='expressReportId'><option value=''>None</option>{reports}</select></label><label>Officer supplemental narrative<textarea name='supplement' rows='6'></textarea></label><button>Save update</button></form></section><section class='card'><h2>Add person</h2><form method='post' action='/police-calls/{id}/people'><input type='hidden' name='__RequestVerificationToken' value='{H(t)}'/><label>Role<input name='role' required placeholder='Victim, suspect, witness, caller, other'/></label><label>First name<input name='firstName'/></label><label>Middle name<input name='middleName'/></label><label>Last name<input name='lastName'/></label><label>DOB<input type='date' name='dob'/></label><label>Phone<input name='phone'/></label><label>Notes<textarea name='notes'></textarea></label><button>Add person</button></form></section><section class='card'><h2>Add vehicle</h2><form method='post' action='/police-calls/{id}/vehicles'><input type='hidden' name='__RequestVerificationToken' value='{H(t)}'/><label>Role<input name='role' placeholder='Suspect vehicle, victim vehicle, involved'/></label><label>Plate<input name='plate'/></label><label>State<input name='plateState'/></label><label>VIN<input name='vin'/></label><label>Year<input name='year'/></label><label>Make<input name='make'/></label><label>Model<input name='model'/></label><label>Color<input name='color'/></label><button>Add vehicle</button></form></section></aside></div></main>"""));
        }).RequireAuthorization();

        app.MapPost("/police-calls/{id:guid}/update",async(Guid id,HttpContext ctx,IAntiforgery anti)=>{if(!CanPolice(ctx.User))return Results.Forbid();await anti.ValidateRequestAsync(ctx);var f=await ctx.Request.ReadFormAsync();var s=f["status"].ToString();if(!new[]{"Open","Assigned","In Progress","Disposition Pending","Closed"}.Contains(s))return Results.BadRequest();var now=Now();await Exec(dbPath,"UPDATE PoliceCalls SET Status=$s,AssignedTo=$a,Disposition=$d,ExpressReportId=NULLIF($r,''),UpdatedAt=$t WHERE Id=$i",("$s",s),("$a",f["assignedTo"]),("$d",f["disposition"]),("$r",f["expressReportId"]),("$t",now),("$i",id));var supp=f["supplement"].ToString().Trim();if(supp.Length>0)await Exec(dbPath,"INSERT INTO PoliceCallSupplements(Id,PoliceCallId,Narrative,AuthoredBy,AuthoredAt) VALUES($i,$c,$n,$b,$t)",("$i",Guid.NewGuid()),("$c",id),("$n",supp),("$b",ctx.User.Identity?.Name??"officer"),("$t",now));await History(dbPath,id,ctx.User.Identity?.Name??"officer","Updated",$"Status {s}; assigned {f["assignedTo"]}; disposition {f["disposition"]}");return Results.Redirect($"/police-calls/{id}");}).RequireAuthorization();
        app.MapPost("/police-calls/{id:guid}/people",async(Guid id,HttpContext ctx,IAntiforgery anti)=>{if(!CanPolice(ctx.User))return Results.Forbid();await anti.ValidateRequestAsync(ctx);var f=await ctx.Request.ReadFormAsync();await Exec(dbPath,"INSERT INTO PoliceCallPeople(Id,PoliceCallId,Role,FirstName,MiddleName,LastName,DateOfBirth,Phone,Notes,CreatedBy,CreatedAt) VALUES($i,$c,$r,$f,$m,$l,$d,$p,$n,$b,$t)",("$i",Guid.NewGuid()),("$c",id),("$r",f["role"]),("$f",f["firstName"]),("$m",f["middleName"]),("$l",f["lastName"]),("$d",f["dob"]),("$p",f["phone"]),("$n",f["notes"]),("$b",ctx.User.Identity?.Name??"officer"),("$t",Now()));await History(dbPath,id,ctx.User.Identity?.Name??"officer","Person added",f["role"]+": "+f["firstName"]+" "+f["lastName"]);return Results.Redirect($"/police-calls/{id}");}).RequireAuthorization();
        app.MapPost("/police-calls/{id:guid}/vehicles",async(Guid id,HttpContext ctx,IAntiforgery anti)=>{if(!CanPolice(ctx.User))return Results.Forbid();await anti.ValidateRequestAsync(ctx);var f=await ctx.Request.ReadFormAsync();await Exec(dbPath,"INSERT INTO PoliceCallVehicles(Id,PoliceCallId,Role,Plate,PlateState,Vin,Year,Make,Model,Color,CreatedBy,CreatedAt) VALUES($i,$c,$r,$p,$ps,$v,$y,$mk,$mo,$co,$b,$t)",("$i",Guid.NewGuid()),("$c",id),("$r",f["role"]),("$p",f["plate"]),("$ps",f["plateState"]),("$v",f["vin"]),("$y",f["year"]),("$mk",f["make"]),("$mo",f["model"]),("$co",f["color"]),("$b",ctx.User.Identity?.Name??"officer"),("$t",Now()));await History(dbPath,id,ctx.User.Identity?.Name??"officer","Vehicle added",f["plate"]+" "+f["make"]+" "+f["model"]);return Results.Redirect($"/police-calls/{id}");}).RequireAuthorization();
    }

    static async Task<(string Number,string Type,string Priority,string Location,string LocationDetails,string CallerName,string CallerPhone,string CallerEmail,bool Anonymous,string SafetyFlags,string Narrative,string Status,string AssignedTo,string Disposition,string? ExpressReportId)?> Load(string p,Guid id){await using var cn=Open(p);await cn.OpenAsync();var c=cn.CreateCommand();c.CommandText="SELECT CallNumber,CallType,Priority,Location,COALESCE(LocationDetails,''),COALESCE(CallerName,''),COALESCE(CallerPhone,''),COALESCE(CallerEmail,''),AnonymousCaller,COALESCE(SafetyFlags,''),InitialNarrative,Status,COALESCE(AssignedTo,''),COALESCE(Disposition,''),ExpressReportId FROM PoliceCalls WHERE Id=$i";c.Parameters.AddWithValue("$i",id.ToString());await using var r=await c.ExecuteReaderAsync();return await r.ReadAsync()?(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetInt32(8)==1,r.GetString(9),r.GetString(10),r.GetString(11),r.GetString(12),r.GetString(13),N(r,14)):null;}
    static async Task<string> People(string p,Guid id){await using var cn=Open(p);await cn.OpenAsync();var c=cn.CreateCommand();c.CommandText="SELECT Role,FirstName,MiddleName,LastName,DateOfBirth,Phone,Notes FROM PoliceCallPeople WHERE PoliceCallId=$i ORDER BY CreatedAt";c.Parameters.AddWithValue("$i",id.ToString());var rows=new List<string>();await using var r=await c.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add($"<article><b>{H(r.GetString(0))}: {H(N(r,1))} {H(N(r,2))} {H(N(r,3))}</b><small>DOB {H(N(r,4))} · {H(N(r,5))}</small><p>{H(N(r,6))}</p></article>");return rows.Count==0?"<p>No people added.</p>":string.Join("",rows);}
    static async Task<string> Vehicles(string p,Guid id){await using var cn=Open(p);await cn.OpenAsync();var c=cn.CreateCommand();c.CommandText="SELECT Role,Plate,PlateState,Vin,Year,Make,Model,Color FROM PoliceCallVehicles WHERE PoliceCallId=$i ORDER BY CreatedAt";c.Parameters.AddWithValue("$i",id.ToString());var rows=new List<string>();await using var r=await c.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add($"<article><b>{H(N(r,0))}: {H(N(r,1))} {H(N(r,2))}</b><small>VIN {H(N(r,3))}</small><p>{H(N(r,4))} {H(N(r,5))} {H(N(r,6))} · {H(N(r,7))}</p></article>");return rows.Count==0?"<p>No vehicles added.</p>":string.Join("",rows);}
    static async Task<string> Supplements(string p,Guid id){await using var cn=Open(p);await cn.OpenAsync();var c=cn.CreateCommand();c.CommandText="SELECT Narrative,AuthoredBy,AuthoredAt FROM PoliceCallSupplements WHERE PoliceCallId=$i ORDER BY AuthoredAt DESC";c.Parameters.AddWithValue("$i",id.ToString());var rows=new List<string>();await using var r=await c.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add($"<article><small>{H(r.GetString(1))} · {H(r.GetString(2))}</small><p style='white-space:pre-wrap'>{H(r.GetString(0))}</p></article>");return rows.Count==0?"<p>No supplements.</p>":string.Join("",rows);}
    static async Task<string> Hist(string p,Guid id){await using var cn=Open(p);await cn.OpenAsync();var c=cn.CreateCommand();c.CommandText="SELECT Actor,Action,Detail,OccurredAt FROM PoliceCallHistory WHERE PoliceCallId=$i ORDER BY OccurredAt DESC";c.Parameters.AddWithValue("$i",id.ToString());var rows=new List<string>();await using var r=await c.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add($"<article><b>{H(r.GetString(1))}</b><small>{H(r.GetString(0))} · {H(r.GetString(3))}</small><p>{H(r.GetString(2))}</p></article>");return string.Join("",rows);}
    static async Task History(string p,Guid id,string actor,string action,string detail)=>await Exec(p,"INSERT INTO PoliceCallHistory(Id,PoliceCallId,Actor,Action,Detail,OccurredAt) VALUES($i,$c,$a,$x,$d,$t)",("$i",Guid.NewGuid()),("$c",id),("$a",actor),("$x",action),("$d",detail),("$t",Now()));
    static async Task<string> ReportOptions(string p,string? selected){await using var cn=Open(p);await cn.OpenAsync();var c=cn.CreateCommand();c.CommandText="SELECT Id,ReportNumber,COALESCE(Title,'') FROM ExpressReports ORDER BY UpdatedAt DESC LIMIT 200";var rows=new List<string>();await using var r=await c.ExecuteReaderAsync();while(await r.ReadAsync()){var id=r.GetString(0);rows.Add($"<option value='{H(id)}' {(id==selected?"selected":"")}>{H(r.GetString(1))} · {H(r.GetString(2))}</option>");}return string.Join("",rows);}
    static void Ensure(string p){using var cn=Open(p);cn.Open();var c=cn.CreateCommand();c.CommandText="CREATE TABLE IF NOT EXISTS PoliceCalls(Id TEXT PRIMARY KEY,CallNumber TEXT NOT NULL UNIQUE,CallType TEXT NOT NULL,Priority TEXT NOT NULL,Location TEXT NOT NULL,LocationDetails TEXT,CallerName TEXT,CallerPhone TEXT NOT NULL,CallerEmail TEXT,CallerRelationship TEXT,AnonymousCaller INTEGER NOT NULL,SafetyFlags TEXT,InitialNarrative TEXT NOT NULL,Status TEXT NOT NULL,AssignedTo TEXT,Disposition TEXT,ExpressReportId TEXT,CreatedBy TEXT NOT NULL,CreatedAt TEXT NOT NULL,UpdatedAt TEXT NOT NULL);CREATE TABLE IF NOT EXISTS PoliceCallPeople(Id TEXT PRIMARY KEY,PoliceCallId TEXT NOT NULL,Role TEXT NOT NULL,FirstName TEXT,MiddleName TEXT,LastName TEXT,DateOfBirth TEXT,Phone TEXT,Notes TEXT,CreatedBy TEXT NOT NULL,CreatedAt TEXT NOT NULL);CREATE TABLE IF NOT EXISTS PoliceCallVehicles(Id TEXT PRIMARY KEY,PoliceCallId TEXT NOT NULL,Role TEXT,Plate TEXT,PlateState TEXT,Vin TEXT,Year TEXT,Make TEXT,Model TEXT,Color TEXT,CreatedBy TEXT NOT NULL,CreatedAt TEXT NOT NULL);CREATE TABLE IF NOT EXISTS PoliceCallSupplements(Id TEXT PRIMARY KEY,PoliceCallId TEXT NOT NULL,Narrative TEXT NOT NULL,AuthoredBy TEXT NOT NULL,AuthoredAt TEXT NOT NULL);CREATE TABLE IF NOT EXISTS PoliceCallHistory(Id TEXT PRIMARY KEY,PoliceCallId TEXT NOT NULL,Actor TEXT NOT NULL,Action TEXT NOT NULL,Detail TEXT NOT NULL,OccurredAt TEXT NOT NULL);CREATE INDEX IF NOT EXISTS IX_PoliceCalls_Status ON PoliceCalls(Status,CreatedAt);CREATE INDEX IF NOT EXISTS IX_PoliceCallPeople_Call ON PoliceCallPeople(PoliceCallId);CREATE INDEX IF NOT EXISTS IX_PoliceCallVehicles_Call ON PoliceCallVehicles(PoliceCallId);";c.ExecuteNonQuery();}
    static bool CanPolice(ClaimsPrincipal u)=>u.IsInRole("Administrator")||u.IsInRole("Supervisor")||u.Claims.Any(c=>c.Type==DepartmentAccess.ClaimType&&string.Equals(c.Value,"Police",StringComparison.OrdinalIgnoreCase));static SqliteConnection Open(string p)=>new($"Data Source={p}");static async Task Exec(string p,string sql,params(string,object?)[] ps){await using var cn=Open(p);await cn.OpenAsync();var c=cn.CreateCommand();c.CommandText=sql;foreach(var x in ps)c.Parameters.AddWithValue(x.Item1,x.Item2?.ToString()??"");await c.ExecuteNonQueryAsync();}static string? N(SqliteDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);static string Now()=>DateTimeOffset.UtcNow.ToString("O");static string H(object? x)=>WebUtility.HtmlEncode(x?.ToString()??"");static string Opts(IEnumerable<string> xs,string? selected)=>string.Join("",xs.Select(x=>$"<option {(string.Equals(x,selected,StringComparison.OrdinalIgnoreCase)?"selected":"")}>{H(x)}</option>"));static IResult Html(string x)=>Results.Content(x,"text/html; charset=utf-8");static string Page(string t,string b)=>$"<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>{H(t)} · CLT++ Employee</title><link rel='stylesheet' href='/app.css'></head><body>{b}</body></html>";
}
